@staticmethod
def _get_path_of_set_action(set_action):
    """Return the full document path of a SET action as a tuple of strings"""
    path = []
    for element in set_action.children[0].children:
        if isinstance(element, ExpressionPathDescender):
            continue
        elif isinstance(element, ExpressionSelector):
            path.append(f"[{element.get_index()}]")
        elif isinstance(element, ExpressionAttributeName):
            path.append(element.get_attribute_name_placeholder())
        else:
            path.append(element.get_attribute_name())
    return tuple(path)

@staticmethod
def _path_to_str(path):
    result = ""
    for part in path:
        if part.startswith("["):
            result += part
        else:
            result += "." + part if result else part
    return result

